const q = $input.first().json.query || {};
const versions = String(q.versions || '').split(',').map((v) => Number(v)).filter((v) => Number.isInteger(v) && v > 0);
const iso = (v) => (v && !Number.isNaN(Date.parse(v)) ? new Date(v).toISOString() : null);
return [{ json: {
  p_tenant_key: q.tenantKey || 'k1_katsastus_demo',
  p_versions: versions.length ? versions : null,
  p_include_draft: q.draft === undefined ? true : q.draft === 'true',
  p_feedback: ['up', 'down', 'none'].includes(q.feedback) ? q.feedback : null,
  p_source: ['playground', 'compare', 'staging'].includes(q.source) ? q.source : null,
  p_from: iso(q.from),
  p_to: iso(q.to),
  p_query: String(q.q || '').slice(0, 200) || null,
  p_limit: Math.min(Number(q.limit) || 50, 200),
  p_offset: Math.max(Number(q.offset) || 0, 0)
} }];

const value = $input.first()?.json;
if (!value || !value.conversation) return [{ json: { error: 'not_found' } }];
const row = value.conversation;
return [{ json: {
  conversation: {
    id: row.id,
    versionId: row.version_id,
    versionNumber: row.version_number,
    isDraft: row.is_draft,
    source: row.source,
    title: row.title,
    startedBy: row.started_by,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    messageCount: Number(row.message_count || 0),
    thumbsUp: Number(row.thumbs_up || 0),
    thumbsDown: Number(row.thumbs_down || 0),
    lastReply: row.last_reply || ''
  },
  messages: value.messages || []
} }];

const req = $('List Webhook').first().json;
const raw = String(req.headers?.['x-k1-session'] || '');
const token = raw.replace(/^Bearer\s+/i, '').trim();
let iss = '';
try {
  const part = token.split('.')[1] || '';
  iss = JSON.parse(Buffer.from(part.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8')).iss || '';
} catch (error) {}
return [{ json: { token: token || 'missing', iss } }];

// Only signed-in members of these Clerk teams can use the agent builder.
const ALLOWED_TEAMS = ["org_3JnrOo6wYLChqTm3DpvDZXlNgW7", "org_3JnkbIdnkJiAQQo7qBAh2vtiXSa"];
const TRUSTED_ISSUERS = ["https://clerk.a-katsastus.wasup.co", "https://maximum-beetle-5151.clerk.accounts.dev"];
const verified = $input.first().json;
const claims = verified.payload || verified;
if (verified.error || !claims || !claims.sub || !TRUSTED_ISSUERS.includes(claims.iss)) {
  return [{ json: { ok: false, status: 401, error: 'signin_required' } }];
}
const team = (claims.o && claims.o.id) || claims.org_id || null;
if (!ALLOWED_TEAMS.includes(team)) {
  return [{ json: { ok: false, status: 403, error: 'team_required' } }];
}
return [{ json: { ok: true } }];

